import { useEffect, useRef, useState } from 'react'
import { product } from '../data/product.js'

export default function SizeSelect({ size, onSizeChange }) {
  const [open, setOpen] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)
  const triggerRef = useRef(null)
  const listRef = useRef(null)

  const selected = product.sizes.find((s) => s.id === size)
  const label = selected ? `Size: ${selected.label}` : 'Select a size'

  useEffect(() => {
    if (!open) return
    const next = selected
      ? product.sizes.findIndex((s) => s.id === size)
      : product.sizes.findIndex((s) => !s.soldOut)
    setActiveIndex(next >= 0 ? next : 0)
    const timer = window.setTimeout(() => {
      listRef.current
        ?.querySelectorAll('[role="option"]')
        [next >= 0 ? next : 0]?.focus()
    }, 0)
    return () => window.clearTimeout(timer)
  }, [open]) // eslint-disable-line react-hooks/exhaustive-deps

  const close = (returnFocus = true) => {
    setOpen(false)
    if (returnFocus) triggerRef.current?.focus()
  }

  const choose = (option) => {
    if (option.soldOut) return
    onSizeChange(option.id)
    close()
  }

  const move = (delta) => {
    const count = product.sizes.length
    let index = activeIndex
    for (let step = 0; step < count; step++) {
      index = (index + delta + count * 2) % count
      if (!product.sizes[index].soldOut) break
    }
    setActiveIndex(index)
    listRef.current?.querySelectorAll('[role="option"]')[index]?.focus()
  }

  const onKeyDown = (event) => {
    switch (event.key) {
      case 'ArrowDown':
      case 'ArrowUp':
        event.preventDefault()
        if (!open) setOpen(true)
        else move(event.key === 'ArrowDown' ? 1 : -1)
        break
      case 'Home':
        if (open) {
          event.preventDefault()
          setActiveIndex(0)
          listRef.current?.querySelector('[role="option"]')?.focus()
        }
        break
      case 'End':
        if (open) {
          event.preventDefault()
          const last = product.sizes.length - 1
          setActiveIndex(last)
          listRef.current
            ?.querySelectorAll('[role="option"]')
            [last]?.focus()
        }
        break
      case 'Escape':
        if (open) close()
        break
      case 'Enter':
      case ' ':
        if (open) {
          event.preventDefault()
          choose(product.sizes[activeIndex])
        }
        break
      default:
        break
    }
  }

  return (
    <div className="size-select">
      <button
        ref={triggerRef}
        type="button"
        id="size-select-button"
        className="size-trigger"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls="size-listbox"
        onClick={() => setOpen((value) => !value)}
        onKeyDown={onKeyDown}
      >
        {label}
      </button>
      <ul
        ref={listRef}
        id="size-listbox"
        role="listbox"
        aria-labelledby="size-select-button"
        className="size-listbox"
        hidden={!open}
        tabIndex={-1}
      >
        {product.sizes.map((option, index) => {
          const optionId = `size-option-${option.id}`
          return (
            <li
              key={option.id}
              id={optionId}
              role="option"
              tabIndex={-1}
              aria-selected={size === option.id}
              aria-disabled={option.soldOut}
              className={index === activeIndex ? 'active' : undefined}
              onClick={() => choose(option)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault()
                  choose(option)
                }
              }}
            >
              {option.label}
              {option.soldOut ? <span className="sold-out">Sold out</span> : null}
            </li>
          )
        })}
      </ul>
    </div>
  )
}
