import { useEffect, useRef, useState } from 'react'
import { recommendedSize } from '../data/product.js'

export default function SizeGuide({ open, onClose }) {
  const dialogRef = useRef(null)
  const firstFieldRef = useRef(null)
  const [footLength, setFootLength] = useState('')
  const [unit, setUnit] = useState('us')
  const [result, setResult] = useState(null)
  const [error, setError] = useState('')

  useEffect(() => {
    if (!open) return
    firstFieldRef.current?.focus()
    const onKeyDown = (event) => {
      if (event.key === 'Escape') onClose()
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [open, onClose])

  if (!open) return null

  const onSubmit = (event) => {
    event.preventDefault()
    if (!footLength || Number(footLength) <= 0) {
      setError('Enter your foot length in centimetres.')
      setResult(null)
      return
    }
    setError('')
    setResult(recommendedSize(footLength, unit))
  }

  return (
    <div className="overlay" onClick={onClose}>
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="size-guide-title"
        className="dialog"
        onClick={(event) => event.stopPropagation()}
      >
        <h2 id="size-guide-title">Size guide</h2>
        <button type="button" className="dialog-close" onClick={onClose}>
          <span aria-hidden="true">✕</span> Close
        </button>
        <p>Measure your foot and we will recommend a size.</p>
        <form onSubmit={onSubmit}>
          <label htmlFor="foot-length">Foot length (cm)</label>
          <input
            ref={firstFieldRef}
            id="foot-length"
            type="number"
            min="10"
            max="40"
            step="0.1"
            value={footLength}
            onChange={(event) => setFootLength(event.target.value)}
          />
          <fieldset>
            <legend>Size unit</legend>
            <label>
              <input
                type="radio"
                name="unit"
                value="us"
                checked={unit === 'us'}
                onChange={() => setUnit('us')}
              />
              US
            </label>
            <label>
              <input
                type="radio"
                name="unit"
                value="eu"
                checked={unit === 'eu'}
                onChange={() => setUnit('eu')}
              />
              EU
            </label>
          </fieldset>
          {error ? (
            <p className="field-error" role="alert">
              {error}
            </p>
          ) : null}
          <button type="submit">Find my size</button>
        </form>
        {result ? (
          <p className="size-result">
            Recommended size: <strong>{result}</strong>
          </p>
        ) : null}
      </div>
    </div>
  )
}
